from pathlib import Path
p=Path(__file__).parent/'dist/app.js';s=p.read_text('utf-8')
old="const blob=zipStore(files),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mg-tour-previa-360.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('ZIP da prévia gerado. Integração 3DVista continua pendente.');"
new="const blob=zipStore(files),url=URL.createObjectURL(blob);modal(`<h2>Prévia pronta para baixar.</h2><p>${p.scenes.length} panoramas · ${Math.round(blob.size/1024/1024)} MB · player independente MG Tour.</p><p>Extraia a pasta completa para testar. Esta prévia não é um projeto nativo 3DVista.</p><a class=\"download-button\" href=\"${url}\" download=\"mg-tour-previa-360.zip\" id=\"preview-zip-download\">Baixar ZIP da prévia</a>`);toast('Pacote preparado. Use o link para baixar.');"
assert old in s;s=s.replace(old,new)
# Preserve the selected composition in the generated standalone player.
needle="$('#close-info').onclick=()=>$('#info').close();load(0);`;"
replacement="""$('#close-info').onclick=()=>$('#info').close();if(p.layout){const geometry=(el,b)=>{el.style.position='fixed';el.style.left=b[0]+'%';el.style.top=b[1]+'%';el.style.width=b[2]+'%';el.style.height=b[3]+'%';el.style.right='auto';el.style.bottom='auto';el.style.transform='none';};geometry(document.querySelector('header'),p.layout.brand);geometry(document.querySelector('nav'),p.layout.dock);geometry(menu,p.layout.menu);geometry($('#scene-name'),p.layout.scene);const panel=p.panel||'#132c29';for(const el of[document.querySelector('header'),document.querySelector('nav'),menu,$('#scene-name')]){el.style.background=panel;el.style.borderRadius=(p.surface?.radius||4)+'px';el.style.padding='8px';el.style.color=panel==='#f1e9e2'?'#293a32':'#fff';}menu.style.zIndex='5';menu.style.maxWidth='none';$('#scene-name').style.display='flex';$('#scene-name').style.alignItems='center';if(p.layout.dock[2]<p.layout.dock[3])document.querySelector('nav').style.flexDirection='column';document.querySelector('nav').style.justifyContent='space-around';document.querySelector('nav').style.alignItems='center';document.querySelector('nav').querySelectorAll('button').forEach(b=>{b.style.padding='5px';b.style.background='transparent';b.style.color=panel==='#f1e9e2'?'#293a32':'#fff';});}load(0);`;"""
assert needle in s;s=s.replace(needle,replacement)
s=s.replace('<select id="scenes" aria-label="Escolher ambiente"></select></header>','</header><select id="scenes" aria-label="Escolher ambiente"></select>')
