s=s.replace("@media(max-width:600px){header{inset:","@media(max-width:600px){nav{left:8%!important;top:86%!important;width:84%!important;height:12%!important;flex-direction:row!important}#scene-name{left:4%!important;top:71%!important;width:58%!important;height:10%!important;font-size:10px}#scenes{left:67%!important;top:71%!important;width:29%!important;height:10%!important;font-size:10px}header{inset:")
p.write_text(s,'utf-8')
